//! cuDNN v8/v9 C API shim for cuda-for-intel.
//!
//! Real implementations: handles, all descriptors, convolution (forward,
//! backward data, backward filter; 2-D, NCHW/NHWC strides, groups, dilation,
//! stride, padding, f32/f16/bf16) through generated PTX, `cudnnAddTensor`,
//! `cudnnConvolutionBiasActivationForward` (identity/ReLU), spatial batch
//! normalization (training, inference, backward) and the v8 backend API for
//! single-convolution graphs. Everything else exports with the right name and
//! returns `CUDNN_STATUS_NOT_SUPPORTED` (see `stubs.rs`, generated by
//! `scripts/gen_cudnn_stubs.py`).
#![allow(non_snake_case, clippy::missing_safety_doc, clippy::too_many_arguments)]

pub mod abi;
pub mod backend;
pub mod desc;
pub mod driver;
pub mod ptxgen;
pub mod refmath;
mod stubs;

use abi::Status;
use desc::*;
use driver::{Arg, CUstream, Kid, LaunchError};
use ptxgen::ConvKind;
use std::ffi::{c_char, c_int, c_void};

macro_rules! trace {
    ($($arg:tt)*) => {
        if std::env::var_os("CFI_CUDNN_TRACE").is_some_and(|v| !v.is_empty() && v != "0") {
            eprintln!("CUDA for Intel cudnn: {}", format!($($arg)*));
        }
    };
}

macro_rules! tri {
    ($e:expr) => {
        match $e {
            Ok(v) => v,
            Err(s) => return s,
        }
    };
}

fn reference<'a, T>(p: *mut T) -> Result<&'a mut T, Status> {
    unsafe { p.as_mut() }.ok_or(abi::BAD_PARAM)
}
fn creference<'a, T>(p: *const T) -> Result<&'a T, Status> {
    unsafe { p.as_ref() }.ok_or(abi::BAD_PARAM)
}
unsafe fn int_slice<'a>(p: *const c_int, n: c_int) -> Result<&'a [i32], Status> {
    if n < 0 || (n > 0 && p.is_null()) {
        return Err(abi::BAD_PARAM);
    }
    Ok(if n == 0 { &[] } else { unsafe { std::slice::from_raw_parts(p, n as usize) } })
}
unsafe fn put<T>(p: *mut T, v: T) {
    if !p.is_null() {
        unsafe { p.write(v) };
    }
}
fn scalar(p: *const c_void) -> Result<f32, Status> {
    if p.is_null() { Err(abi::BAD_PARAM) } else { Ok(unsafe { *(p as *const f32) }) }
}

// ---------------------------------------------------------------------------
// Handle, version, errors
// ---------------------------------------------------------------------------

pub struct Handle {
    stream: CUstream,
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetVersion() -> usize {
    abi::VERSION
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetMaxDeviceVersion() -> usize {
    900
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetCudartVersion() -> usize {
    if cfg!(feature = "v8") { 11080 } else { 12080 }
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetProperty(prop: c_int, value: *mut c_int) -> Status {
    let v = match prop {
        0 => abi::MAJOR,
        1 => abi::MINOR,
        2 => abi::PATCH,
        _ => return abi::BAD_PARAM,
    };
    unsafe { put(value, v) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetErrorString(status: Status) -> *const c_char {
    abi::status_name(status).as_ptr().cast()
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetLastErrorString(message: *mut c_char, max_size: usize) {
    if !message.is_null() && max_size > 0 {
        unsafe { *message = 0 };
    }
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnQueryRuntimeError(_h: *mut Handle, rstatus: *mut Status, _mode: c_int, _tag: *mut c_void) -> Status {
    unsafe { put(rstatus, abi::SUCCESS) };
    abi::SUCCESS
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnCreate(handle: *mut *mut Handle) -> Status {
    if handle.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { *handle = Box::into_raw(Box::new(Handle { stream: std::ptr::null_mut() })) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnDestroy(handle: *mut Handle) -> Status {
    if handle.is_null() {
        return abi::BAD_PARAM;
    }
    drop(unsafe { Box::from_raw(handle) });
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetStream(handle: *mut Handle, stream: CUstream) -> Status {
    tri!(reference(handle)).stream = stream;
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetStream(handle: *mut Handle, stream: *mut CUstream) -> Status {
    let h = tri!(reference(handle));
    if stream.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { *stream = h.stream };
    abi::SUCCESS
}

macro_rules! version_checks {
    ($($n:ident),*) => { $(
        #[unsafe(no_mangle)]
        pub unsafe extern "system" fn $n() -> Status { abi::SUCCESS }
    )* };
}
version_checks!(
    cudnnGraphVersionCheck, cudnnOpsVersionCheck, cudnnCnnVersionCheck, cudnnAdvVersionCheck,
    cudnnOpsInferVersionCheck, cudnnOpsTrainVersionCheck, cudnnCnnInferVersionCheck,
    cudnnCnnTrainVersionCheck, cudnnAdvInferVersionCheck, cudnnAdvTrainVersionCheck
);

