// Tensor descriptors
// ---------------------------------------------------------------------------

type Td = *mut TensorDesc;

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnCreateTensorDescriptor(out: *mut Td) -> Status {
    if out.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { *out = Box::into_raw(Box::default()) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnDestroyTensorDescriptor(d: Td) -> Status {
    if d.is_null() {
        return abi::BAD_PARAM;
    }
    drop(unsafe { Box::from_raw(d) });
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetTensor4dDescriptor(d: Td, format: c_int, dt: c_int, n: c_int, c: c_int, h: c_int, w: c_int) -> Status {
    tri!(reference(d)).set_4d(format, dt, n, c, h, w)
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetTensor4dDescriptorEx(
    d: Td, dt: c_int, n: c_int, c: c_int, h: c_int, w: c_int, ns: c_int, cs: c_int, hs: c_int, ws: c_int,
) -> Status {
    tri!(reference(d)).set_nd(dt, &[n, c, h, w], &[ns, cs, hs, ws])
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetTensor4dDescriptor(
    d: Td, dt: *mut c_int, n: *mut c_int, c: *mut c_int, h: *mut c_int, w: *mut c_int, ns: *mut c_int, cs: *mut c_int,
    hs: *mut c_int, ws: *mut c_int,
) -> Status {
    let t = tri!(reference(d));
    if t.dims.len() != 4 {
        return abi::BAD_PARAM;
    }
    unsafe {
        put(dt, t.dtype);
        for (p, v) in [(n, t.dims[0]), (c, t.dims[1]), (h, t.dims[2]), (w, t.dims[3]), (ns, t.strides[0]), (cs, t.strides[1]), (hs, t.strides[2]), (ws, t.strides[3])] {
            put(p, v);
        }
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetTensorNdDescriptor(d: Td, dt: c_int, nb: c_int, dims: *const c_int, strides: *const c_int) -> Status {
    let (dims, strides) = (tri!(unsafe { int_slice(dims, nb) }), tri!(unsafe { int_slice(strides, nb) }));
    tri!(reference(d)).set_nd(dt, dims, strides)
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetTensorNdDescriptorEx(d: Td, format: c_int, dt: c_int, nb: c_int, dims: *const c_int) -> Status {
    let dims = tri!(unsafe { int_slice(dims, nb) });
    tri!(reference(d)).set_nd_ex(format, dt, dims)
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetTensorNdDescriptor(
    d: Td, requested: c_int, dt: *mut c_int, nb: *mut c_int, dims: *mut c_int, strides: *mut c_int,
) -> Status {
    let t = tri!(reference(d));
    if requested < 0 || !t.is_set() {
        return abi::BAD_PARAM;
    }
    unsafe {
        put(dt, t.dtype);
        put(nb, t.dims.len() as c_int);
        if !dims.is_null() && !strides.is_null() {
            for i in 0..(requested as usize).min(t.dims.len()) {
                *dims.add(i) = t.dims[i];
                *strides.add(i) = t.strides[i];
            }
        }
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetTensorSizeInBytes(d: Td, size: *mut usize) -> Status {
    let t = tri!(reference(d));
    if !t.is_set() || size.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { *size = t.size_in_bytes() };
    abi::SUCCESS
}

