type Cd = *mut ConvDesc;

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnCreateConvolutionDescriptor(out: *mut Cd) -> Status {
    if out.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { *out = Box::into_raw(Box::default()) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnDestroyConvolutionDescriptor(d: Cd) -> Status {
    if d.is_null() {
        return abi::BAD_PARAM;
    }
    drop(unsafe { Box::from_raw(d) });
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetConvolution2dDescriptor(
    d: Cd, ph: c_int, pw: c_int, u: c_int, v: c_int, dh: c_int, dw: c_int, mode: c_int, compute: c_int,
) -> Status {
    tri!(reference(d)).set_nd(&[ph, pw], &[u, v], &[dh, dw], mode, compute)
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetConvolution2dDescriptor(
    d: Cd, ph: *mut c_int, pw: *mut c_int, u: *mut c_int, v: *mut c_int, dh: *mut c_int, dw: *mut c_int, mode: *mut c_int,
    compute: *mut c_int,
) -> Status {
    let c = tri!(reference(d));
    if c.pad.len() != 2 {
        return abi::BAD_PARAM;
    }
    unsafe {
        for (p, val) in [(ph, c.pad[0]), (pw, c.pad[1]), (u, c.stride[0]), (v, c.stride[1]), (dh, c.dilation[0]), (dw, c.dilation[1]), (mode, c.mode), (compute, c.compute_type)] {
            put(p, val);
        }
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetConvolutionNdDescriptor(
    d: Cd, n: c_int, pad: *const c_int, stride: *const c_int, dil: *const c_int, mode: c_int, compute: c_int,
) -> Status {
    let (p, s, di) = (tri!(unsafe { int_slice(pad, n) }), tri!(unsafe { int_slice(stride, n) }), tri!(unsafe { int_slice(dil, n) }));
    tri!(reference(d)).set_nd(p, s, di, mode, compute)
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetConvolutionNdDescriptor(
    d: Cd, requested: c_int, len: *mut c_int, pad: *mut c_int, stride: *mut c_int, dil: *mut c_int, mode: *mut c_int,
    compute: *mut c_int,
) -> Status {
    let c = tri!(reference(d));
    if requested < 0 {
        return abi::BAD_PARAM;
    }
    unsafe {
        put(len, c.pad.len() as c_int);
        put(mode, c.mode);
        put(compute, c.compute_type);
        for i in 0..(requested as usize).min(c.pad.len()) {
            if !pad.is_null() {
                *pad.add(i) = c.pad[i];
            }
            if !stride.is_null() {
                *stride.add(i) = c.stride[i];
            }
            if !dil.is_null() {
                *dil.add(i) = c.dilation[i];
            }
        }
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetConvolutionMathType(d: Cd, m: c_int) -> Status {
    if !(0..=3).contains(&m) {
        return abi::BAD_PARAM;
    }
    tri!(reference(d)).math_type = m;
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetConvolutionMathType(d: Cd, m: *mut c_int) -> Status {
    let c = tri!(reference(d));
    unsafe { put(m, c.math_type) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetConvolutionGroupCount(d: Cd, g: c_int) -> Status {
    if g < 1 {
        return abi::BAD_PARAM;
    }
    tri!(reference(d)).groups = g;
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetConvolutionGroupCount(d: Cd, g: *mut c_int) -> Status {
    let c = tri!(reference(d));
    unsafe { put(g, c.groups) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetConvolutionReorderType(d: Cd, r: c_int) -> Status {
    if !(0..=1).contains(&r) {
        return abi::BAD_PARAM;
    }
    tri!(reference(d)).reorder = r;
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetConvolutionReorderType(d: Cd, r: *mut c_int) -> Status {
    let c = tri!(reference(d));
    unsafe { put(r, c.reorder) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetConvolution2dForwardOutputDim(
    c: Cd, x: Td, w: Fd, n: *mut c_int, ch: *mut c_int, h: *mut c_int, wd: *mut c_int,
) -> Status {
    let dims = tri!(forward_output_dims(tri!(reference(x)), tri!(reference(w)), tri!(reference(c))));
    if dims.len() != 4 {
        return abi::BAD_PARAM;
    }
    unsafe {
        for (p, v) in [(n, dims[0]), (ch, dims[1]), (h, dims[2]), (wd, dims[3])] {
            put(p, v);
        }
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetConvolutionNdForwardOutputDim(c: Cd, x: Td, w: Fd, nb: c_int, out: *mut c_int) -> Status {
    let dims = tri!(forward_output_dims(tri!(reference(x)), tri!(reference(w)), tri!(reference(c))));
    if nb as usize != dims.len() || out.is_null() {
        return abi::BAD_PARAM;
    }
    for (i, v) in dims.iter().enumerate() {
        unsafe { *out.add(i) = *v };
    }
    abi::SUCCESS
}

