type Pd = *mut PoolingDesc;

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnCreatePoolingDescriptor(out: *mut Pd) -> Status {
    if out.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { *out = Box::into_raw(Box::default()) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnDestroyPoolingDescriptor(d: Pd) -> Status {
    if d.is_null() {
        return abi::BAD_PARAM;
    }
    drop(unsafe { Box::from_raw(d) });
    abi::SUCCESS
}
fn set_pooling(p: &mut PoolingDesc, mode: c_int, nan: c_int, win: &[i32], pad: &[i32], stride: &[i32]) -> Status {
    if !(0..=3).contains(&mode) || !(0..=1).contains(&nan) || win.is_empty() || win.len() != pad.len() || win.len() != stride.len() {
        return abi::BAD_PARAM;
    }
    if win.iter().any(|v| *v <= 0) || stride.iter().any(|v| *v <= 0) || pad.iter().any(|v| *v < 0) {
        return abi::BAD_PARAM;
    }
    *p = PoolingDesc { mode, nan_opt: nan, window: win.to_vec(), pad: pad.to_vec(), stride: stride.to_vec() };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetPooling2dDescriptor(
    d: Pd, mode: c_int, nan: c_int, wh: c_int, ww: c_int, vpad: c_int, hpad: c_int, vstride: c_int, hstride: c_int,
) -> Status {
    set_pooling(tri!(reference(d)), mode, nan, &[wh, ww], &[vpad, hpad], &[vstride, hstride])
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetPooling2dDescriptor(
    d: Pd, mode: *mut c_int, nan: *mut c_int, wh: *mut c_int, ww: *mut c_int, vpad: *mut c_int, hpad: *mut c_int,
    vstride: *mut c_int, hstride: *mut c_int,
) -> Status {
    let p = tri!(reference(d));
    if p.window.len() != 2 {
        return abi::BAD_PARAM;
    }
    unsafe {
        put(mode, p.mode);
        put(nan, p.nan_opt);
        for (q, v) in [(wh, p.window[0]), (ww, p.window[1]), (vpad, p.pad[0]), (hpad, p.pad[1]), (vstride, p.stride[0]), (hstride, p.stride[1])] {
            put(q, v);
        }
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnSetPoolingNdDescriptor(
    d: Pd, mode: c_int, nan: c_int, n: c_int, win: *const c_int, pad: *const c_int, stride: *const c_int,
) -> Status {
    let (w, p, s) = (tri!(unsafe { int_slice(win, n) }), tri!(unsafe { int_slice(pad, n) }), tri!(unsafe { int_slice(stride, n) }));
    set_pooling(tri!(reference(d)), mode, nan, w, p, s)
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetPoolingNdDescriptor(
    d: Pd, requested: c_int, mode: *mut c_int, nan: *mut c_int, n: *mut c_int, win: *mut c_int, pad: *mut c_int,
    stride: *mut c_int,
) -> Status {
    let p = tri!(reference(d));
    unsafe {
        put(mode, p.mode);
        put(nan, p.nan_opt);
        put(n, p.window.len() as c_int);
        for i in 0..(requested.max(0) as usize).min(p.window.len()) {
            if !win.is_null() { *win.add(i) = p.window[i]; }
            if !pad.is_null() { *pad.add(i) = p.pad[i]; }
            if !stride.is_null() { *stride.add(i) = p.stride[i]; }
        }
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetPoolingNdForwardOutputDim(p: Pd, x: Td, nb: c_int, out: *mut c_int) -> Status {
    let dims = tri!(pooling_output_dims(tri!(reference(p)), tri!(reference(x))));
    if nb as usize != dims.len() || out.is_null() {
        return abi::BAD_PARAM;
    }
    for (i, v) in dims.iter().enumerate() {
        unsafe { *out.add(i) = *v };
    }
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnGetPooling2dForwardOutputDim(p: Pd, x: Td, n: *mut c_int, c: *mut c_int, h: *mut c_int, w: *mut c_int) -> Status {
    let dims = tri!(pooling_output_dims(tri!(reference(p)), tri!(reference(x))));
    if dims.len() != 4 {
        return abi::BAD_PARAM;
    }
    unsafe {
        for (q, v) in [(n, dims[0]), (c, dims[1]), (h, dims[2]), (w, dims[3])] {
            put(q, v);
        }
    }
    abi::SUCCESS
}

