// ---------------------------------------------------------------------------
// Kernel launch helpers
// ---------------------------------------------------------------------------

fn launch_status(r: Result<(), LaunchError>, what: &str) -> Status {
    match r {
        Ok(()) => abi::SUCCESS,
        Err(LaunchError::NoDriver) | Err(LaunchError::NoContext) => abi::NOT_INITIALIZED,
        Err(LaunchError::Module(e)) => {
            eprintln!("CUDA for Intel cudnn: module load for {what} failed err={e}");
            abi::INTERNAL_ERROR
        }
        Err(LaunchError::Launch(e)) => {
            eprintln!("CUDA for Intel cudnn: launch of {what} failed err={e}");
            abi::EXECUTION_FAILED
        }
    }
}

fn conv_kind(d: Dir) -> (ConvKind, refmath::Kind) {
    match d {
        Dir::Fwd => (ConvKind::Fwd, refmath::Kind::Fwd),
        Dir::BwdData => (ConvKind::BwdData, refmath::Kind::BwdData),
        Dir::BwdFilter => (ConvKind::BwdFilter, refmath::Kind::BwdFilter),
    }
}

/// Run one convolution kernel. Operand roles follow `ptxgen::generate_conv`.
fn run_conv(stream: CUstream, plan: &ConvPlan, a: u64, b: u64, out: u64, alpha: f32, beta: f32) -> Status {
    if a == 0 || b == 0 || out == 0 {
        return abi::BAD_PARAM;
    }
    let (gk, rk) = conv_kind(plan.dir);
    let total = plan.geom.total(rk);
    if total == 0 {
        return abi::SUCCESS;
    }
    let mut args = vec![Arg::P(a), Arg::P(b), Arg::P(out), Arg::F(alpha), Arg::F(beta)];
    args.extend(plan.geom.kernel_args(rk).iter().map(|v| Arg::U(*v)));
    trace!("conv {:?} {:?} {:?}", plan.dir, plan.elem, plan.geom);
    launch_status(driver::launch(Kid::Conv(gk, plan.elem), total.div_ceil(256), 256, stream, &args), "conv")
}

/// Fold an Nd (3..=8 dims) tensor pair to the 4-D logical shape the elementwise kernels use.
/// `sa`/`sc` are the strides of the two operands (broadcast operand already has 0 strides).
pub fn fold4(dims: &[i32], sa: &[i32], sc: &[i32]) -> Result<([u32; 4], [u32; 4], [u32; 4]), Status> {
    let (mut d, mut a, mut c): (Vec<i64>, Vec<i64>, Vec<i64>) =
        (dims.iter().map(|v| *v as i64).collect(), sa.iter().map(|v| *v as i64).collect(), sc.iter().map(|v| *v as i64).collect());
    while d.len() < 4 {
        d.push(1);
        a.push(1);
        c.push(1);
    }
    while d.len() > 4 {
        let l = d.len();
        // merge the last two dims when both operands see them as one contiguous run
        if a[l - 2] == d[l - 1] * a[l - 1] && c[l - 2] == d[l - 1] * c[l - 1] {
            d[l - 2] *= d[l - 1];
            a[l - 2] = a[l - 1];
            c[l - 2] = c[l - 1];
            d.pop();
            a.pop();
            c.pop();
        } else if d.len() > 4 && d[l - 1] == 1 {
            d.pop();
            a.pop();
            c.pop();
        } else {
            return Err(abi::NOT_SUPPORTED);
        }
    }
    let cv = |v: &Vec<i64>| -> Result<[u32; 4], Status> {
        if v.iter().any(|x| *x < 0 || *x > u32::MAX as i64) {
            return Err(abi::NOT_SUPPORTED);
        }
        Ok([v[0] as u32, v[1] as u32, v[2] as u32, v[3] as u32])
    };
    Ok((cv(&d)?, cv(&a)?, cv(&c)?))
}

/// `C = alpha*broadcast(A) + beta*C`.
fn run_add_tensor(stream: CUstream, alpha: f32, ad: &TensorDesc, a: u64, beta: f32, cd: &TensorDesc, c: u64) -> Status {
    if a == 0 || c == 0 {
        return abi::BAD_PARAM;
    }
    if ad.dims.len() != cd.dims.len() || !ad.is_set() || !cd.is_set() {
        return abi::BAD_PARAM;
    }
    if ad.dtype != cd.dtype {
        return abi::NOT_SUPPORTED;
    }
    let Some(elem) = elem_of(cd.dtype) else { return abi::NOT_SUPPORTED };
    let mut sa = ad.strides.clone();
    for i in 0..ad.dims.len() {
        if ad.dims[i] != cd.dims[i] && ad.dims[i] != 1 {
            return abi::BAD_PARAM;
        }
        if ad.dims[i] == 1 {
            sa[i] = 0;
        }
    }
    let (dims, sa, sc) = tri!(fold4(&cd.dims, &sa, &cd.strides));
    let total: u64 = dims.iter().map(|v| *v as u64).product();
    if total == 0 || total > u32::MAX as u64 {
        return if total == 0 { abi::SUCCESS } else { abi::NOT_SUPPORTED };
    }
    let mut args = vec![Arg::P(a), Arg::P(c), Arg::F(alpha), Arg::F(beta)];
    args.extend(dims.iter().chain(&sa).chain(&sc).map(|v| Arg::U(*v)));
    args.push(Arg::U(total as u32));
    launch_status(driver::launch(Kid::Add(elem), (total as u32).div_ceil(256), 256, stream, &args), "add_tensor")
}

fn run_relu(stream: CUstream, yd: &TensorDesc, y: u64) -> Status {
    let Some(elem) = elem_of(yd.dtype) else { return abi::NOT_SUPPORTED };
    let (dims, st, _) = tri!(fold4(&yd.dims, &yd.strides, &yd.strides));
    let total: u64 = dims.iter().map(|v| *v as u64).product();
    if total == 0 {
        return abi::SUCCESS;
    }
    let mut args = vec![Arg::P(y)];
    args.extend(dims.iter().chain(&st).map(|v| Arg::U(*v)));
    args.push(Arg::U(total as u32));
    launch_status(driver::launch(Kid::Relu(elem), (total as u32).div_ceil(256), 256, stream, &args), "relu")
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnAddTensor(h: *mut Handle, alpha: *const c_void, ad: Td, a: *const c_void, beta: *const c_void, cd: Td, c: *mut c_void) -> Status {
    let hd = tri!(reference(h));
    let (al, be) = (tri!(scalar(alpha)), tri!(scalar(beta)));
    run_add_tensor(hd.stream, al, tri!(reference(ad)), a as u64, be, tri!(reference(cd)), c as u64)
}

