unsafe fn report_algos(plan: Result<ConvPlan, Status>, algo: i32, requested: c_int, returned: *mut c_int, perf: *mut abi::AlgoPerf) -> Status {
    if requested <= 0 || returned.is_null() || perf.is_null() {
        return abi::BAD_PARAM;
    }
    match plan {
        Ok(_) => unsafe {
            *perf = perf_entry(algo, 1.0);
            *returned = 1;
            abi::SUCCESS
        },
        Err(s) => {
            trace!("algorithm query -> status {s}");
            unsafe { *returned = 0 };
            s
        }
    }
}

