/// y = act(alpha1 * conv(x, w) + alpha2 * z + bias), act in {identity, relu}.
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnConvolutionBiasActivationForward(
    h: *mut Handle, alpha1: *const c_void, x: Td, xp: *const c_void, w: Fd, wp: *const c_void, conv: Cd, _algo: c_int,
    _ws: *mut c_void, _wsb: usize, alpha2: *const c_void, z: Td, zp: *const c_void, bias: Td, biasp: *const c_void,
    act: *mut ActivationDesc, y: Td, yp: *mut c_void,
) -> Status {
    let hd = tri!(reference(h));
    let (a1, a2) = (tri!(scalar(alpha1)), tri!(scalar(alpha2)));
    let act = tri!(reference(act));
    if act.mode != abi::ACT_RELU && act.mode != abi::ACT_IDENTITY {
        return abi::NOT_SUPPORTED;
    }
    let (xd, yd) = (tri!(reference(x)), tri!(reference(y)));
    let plan = tri!(plan_conv(Dir::Fwd, xd, tri!(reference(w)), tri!(reference(conv)), yd));
    let use_z = a2 != 0.0 && !zp.is_null();
    let aliased = use_z && zp as u64 == yp as u64;
    let st = run_conv(hd.stream, &plan, xp as u64, wp as u64, yp as u64, a1, if aliased { a2 } else { 0.0 });
    if st != abi::SUCCESS {
        return st;
    }
    if use_z && !aliased {
        let st = run_add_tensor(hd.stream, a2, tri!(reference(z)), zp as u64, 1.0, yd, yp as u64);
        if st != abi::SUCCESS {
            return st;
        }
    }
    if !biasp.is_null() {
        let st = run_add_tensor(hd.stream, 1.0, tri!(reference(bias)), biasp as u64, 1.0, yd, yp as u64);
        if st != abi::SUCCESS {
            return st;
        }
    }
    if act.mode == abi::ACT_RELU {
        return run_relu(hd.stream, yd, yp as u64);
    }
    abi::SUCCESS
}

// ---------------------------------------------------------------------------
// Batch normalization (spatial modes)
// ---------------------------------------------------------------------------

fn bn_dims_args(p: &BnPlan) -> Vec<Arg> {
    let mut v = vec![Arg::U(p.n), Arg::U(p.c), Arg::U(p.hw), Arg::U(p.w)];
    v.extend(p.strides.iter().map(|s| Arg::U(*s)));
    v
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnDeriveBNTensorDescriptor(derived: Td, x: Td, mode: c_int) -> Status {
    let xd = tri!(reference(x));
    if xd.dims.len() < 4 {
        return abi::BAD_PARAM;
    }
    let mut dims = vec![1; xd.dims.len()];
    dims[1] = xd.dims[1];
    if mode == abi::BN_PER_ACTIVATION {
        dims = xd.dims.clone();
        dims[0] = 1;
    }
    let dt = if xd.dtype == abi::DT_DOUBLE { abi::DT_DOUBLE } else { abi::DT_FLOAT };
    tri!(reference(derived)).set_nd_ex(abi::NCHW, dt, &dims)
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBatchNormalizationForwardTraining(
    h: *mut Handle, mode: c_int, alpha: *const c_void, beta: *const c_void, x: Td, xp: *const c_void, y: Td, yp: *mut c_void,
    bnd: Td, scale: *const c_void, bias: *const c_void, factor: f64, run_mean: *mut c_void, run_var: *mut c_void, eps: f64,
    save_mean: *mut c_void, save_inv: *mut c_void,
) -> Status {
    let hd = tri!(reference(h));
    let (al, be) = (tri!(scalar(alpha)), tri!(scalar(beta)));
    let plan = tri!(plan_bn(mode, tri!(reference(x)), tri!(reference(y)), tri!(reference(bnd))));
    if xp.is_null() || yp.is_null() || scale.is_null() || bias.is_null() || run_mean.is_null() != run_var.is_null() {
        return abi::BAD_PARAM;
    }
    let mut args = vec![
        Arg::P(xp as u64), Arg::P(yp as u64), Arg::P(scale as u64), Arg::P(bias as u64), Arg::P(run_mean as u64),
        Arg::P(run_var as u64), Arg::P(save_mean as u64), Arg::P(save_inv as u64), Arg::F(al), Arg::F(be),
        Arg::F(factor as f32), Arg::F(eps as f32),
    ];
    args.extend(bn_dims_args(&plan));
    trace!("bn train {:?} n={} c={} hw={}", plan.elem, plan.n, plan.c, plan.hw);
    launch_status(driver::launch(Kid::BnTrain(plan.elem), plan.c, ptxgen::BN_BLOCK, hd.stream, &args), "bn_train")
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBatchNormalizationForwardInference(
    h: *mut Handle, mode: c_int, alpha: *const c_void, beta: *const c_void, x: Td, xp: *const c_void, y: Td, yp: *mut c_void,
    bnd: Td, scale: *const c_void, bias: *const c_void, mean: *const c_void, var: *const c_void, eps: f64,
) -> Status {
    let hd = tri!(reference(h));
    let (al, be) = (tri!(scalar(alpha)), tri!(scalar(beta)));
    let plan = tri!(plan_bn(mode, tri!(reference(x)), tri!(reference(y)), tri!(reference(bnd))));
    if xp.is_null() || yp.is_null() || scale.is_null() || bias.is_null() || mean.is_null() || var.is_null() {
        return abi::BAD_PARAM;
    }
    let mut args = vec![
        Arg::P(xp as u64), Arg::P(yp as u64), Arg::P(scale as u64), Arg::P(bias as u64), Arg::P(mean as u64),
        Arg::P(var as u64), Arg::F(al), Arg::F(be), Arg::F(eps as f32),
    ];
    args.extend(bn_dims_args(&plan));
    let total = plan.n as u64 * plan.c as u64 * plan.hw as u64;
    if total == 0 || total > u32::MAX as u64 {
        return if total == 0 { abi::SUCCESS } else { abi::NOT_SUPPORTED };
    }
    launch_status(driver::launch(Kid::BnInfer(plan.elem), (total as u32).div_ceil(256), 256, hd.stream, &args), "bn_infer")
}

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBatchNormalizationBackward(
    h: *mut Handle, mode: c_int, a_data: *const c_void, b_data: *const c_void, a_param: *const c_void, b_param: *const c_void,
    x: Td, xp: *const c_void, dy: Td, dyp: *const c_void, dx: Td, dxp: *mut c_void, bnd: Td, scale: *const c_void,
    d_scale: *mut c_void, d_bias: *mut c_void, eps: f64, saved_mean: *const c_void, saved_inv: *const c_void,
) -> Status {
    let hd = tri!(reference(h));
    let (ad, bd, ap, bp) = (tri!(scalar(a_data)), tri!(scalar(b_data)), tri!(scalar(a_param)), tri!(scalar(b_param)));
    let (xd, dyd, dxd) = (tri!(reference(x)), tri!(reference(dy)), tri!(reference(dx)));
    if dyd.dims != xd.dims || dyd.strides != xd.strides || dyd.dtype != xd.dtype {
        return abi::NOT_SUPPORTED;
    }
    let plan = tri!(plan_bn(mode, xd, dxd, tri!(reference(bnd))));
    if xp.is_null() || dyp.is_null() || dxp.is_null() || scale.is_null() || d_scale.is_null() || d_bias.is_null() {
        return abi::BAD_PARAM;
    }
    let mut args = vec![
        Arg::P(xp as u64), Arg::P(dyp as u64), Arg::P(dxp as u64), Arg::P(scale as u64), Arg::P(d_scale as u64),
        Arg::P(d_bias as u64), Arg::P(saved_mean as u64), Arg::P(saved_inv as u64), Arg::F(ad), Arg::F(bd), Arg::F(ap),
        Arg::F(bp), Arg::F(eps as f32),
    ];
    args.extend(bn_dims_args(&plan));
    launch_status(driver::launch(Kid::BnBwd(plan.elem), plan.c, ptxgen::BN_BLOCK, hd.stream, &args), "bn_bwd")
}


