/// Never unwind across the C ABI: a panic becomes INTERNAL_ERROR.
fn guard(what: &str, f: impl FnOnce() -> Status) -> Status {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(s) => s,
        Err(_) => {
            eprintln!("CUDA for Intel cudnn: internal panic in {what}");
            abi::INTERNAL_ERROR
        }
    }
}

// ---------------------------------------------------------------------------
// v8 backend API
// ---------------------------------------------------------------------------

#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBackendCreateDescriptor(ty: c_int, out: *mut backend::BPtr) -> Status {
    if out.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { *out = tri!(backend::create(ty)) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBackendDestroyDescriptor(d: backend::BPtr) -> Status {
    if d.is_null() {
        return abi::BAD_PARAM;
    }
    unsafe { backend::destroy(d) };
    abi::SUCCESS
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBackendFinalize(d: backend::BPtr) -> Status {
    guard("cudnnBackendFinalize", || {
        let st = unsafe { backend::finalize(tri!(reference(d))) };
        trace!("backend finalize type={} -> {st}", unsafe { (*d).ty });
        st
    })
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBackendSetAttribute(d: backend::BPtr, name: c_int, ty: c_int, count: i64, data: *const c_void) -> Status {
    guard("cudnnBackendSetAttribute", || {
        let st = unsafe { backend::set_attribute(tri!(reference(d)), name, ty, count, data as *const u8) };
        trace!("backend set type={} attr={name} atype={ty} n={count} -> {st}", unsafe { (*d).ty });
        st
    })
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBackendGetAttribute(
    d: backend::BPtr, name: c_int, ty: c_int, requested: i64, count: *mut i64, out: *mut c_void,
) -> Status {
    guard("cudnnBackendGetAttribute", || {
        let st = unsafe { backend::get_attribute(tri!(creference(d as *const backend::BDesc)), name, ty, requested, count, out as *mut u8) };
        trace!("backend get type={} attr={name} atype={ty} req={requested} -> {st}", unsafe { (*d).ty });
        st
    })
}
#[unsafe(no_mangle)]
pub unsafe extern "system" fn cudnnBackendExecute(h: *mut Handle, plan: backend::BPtr, vp: backend::BPtr) -> Status {
    guard("cudnnBackendExecute", || {
        let hd = tri!(reference(h));
        let (plan, vp) = (tri!(reference(plan)), tri!(reference(vp)));
        if plan.ty != abi::BD_EXECUTION_PLAN || vp.ty != abi::BD_VARIANT_PACK || !plan.finalized || !vp.finalized {
            return abi::BAD_PARAM;
        }
        let Some(e) = plan.exec else { return abi::BAD_PARAM };
        let ptrs = tri!(backend::resolve_pointers(vp, &e.uids));
        run_conv(hd.stream, &plan_exec_plan(&e), ptrs[0], ptrs[1], ptrs[2], e.alpha, e.beta)
    })
}
fn plan_exec_plan(e: &backend::PlanExec) -> ConvPlan {
    e.plan
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::ptr::null_mut;

    #[test]
    fn handle_lifecycle_and_versions() {
        unsafe {
            let mut h = null_mut();
            assert_eq!(cudnnCreate(&mut h), abi::SUCCESS);
            assert_eq!(cudnnSetStream(h, 0x1234 as CUstream), abi::SUCCESS);
            let mut s = null_mut();
            assert_eq!(cudnnGetStream(h, &mut s), abi::SUCCESS);
            assert_eq!(s as usize, 0x1234);
            assert_eq!(cudnnDestroy(h), abi::SUCCESS);
            assert_eq!(cudnnDestroy(null_mut()), abi::BAD_PARAM);
            assert_eq!(cudnnGetVersion(), abi::VERSION);
            let mut major = 0;
            assert_eq!(cudnnGetProperty(0, &mut major), abi::SUCCESS);
            assert_eq!(major, abi::MAJOR);
            assert_eq!(std::ffi::CStr::from_ptr(cudnnGetErrorString(abi::NOT_SUPPORTED)).to_str().unwrap(), "CUDNN_STATUS_NOT_SUPPORTED");
        }
    }

    #[test]
    fn descriptors_round_trip_through_c_api() {
        unsafe {
            let mut t = null_mut();
            assert_eq!(cudnnCreateTensorDescriptor(&mut t), abi::SUCCESS);
            assert_eq!(cudnnSetTensor4dDescriptor(t, abi::NHWC, abi::DT_HALF, 2, 3, 4, 5), abi::SUCCESS);
            let (mut dt, mut nb) = (0, 0);
            let (mut dims, mut st) = ([0; 8], [0; 8]);
            assert_eq!(cudnnGetTensorNdDescriptor(t, 8, &mut dt, &mut nb, dims.as_mut_ptr(), st.as_mut_ptr()), abi::SUCCESS);
            assert_eq!((dt, nb, &dims[..4], &st[..4]), (abi::DT_HALF, 4, &[2, 3, 4, 5][..], &[60, 1, 15, 3][..]));
            let mut sz = 0;
            assert_eq!(cudnnGetTensorSizeInBytes(t, &mut sz), abi::SUCCESS);
            assert_eq!(sz, 240);
            assert_eq!(cudnnDestroyTensorDescriptor(t), abi::SUCCESS);
            let mut c = null_mut();
            cudnnCreateConvolutionDescriptor(&mut c);
            assert_eq!(cudnnSetConvolution2dDescriptor(c, 1, 2, 3, 4, 5, 6, abi::CROSS_CORRELATION, abi::DT_FLOAT), abi::SUCCESS);
            let mut v = [0; 8];
            assert_eq!(
                cudnnGetConvolution2dDescriptor(c, &mut v[0], &mut v[1], &mut v[2], &mut v[3], &mut v[4], &mut v[5], &mut v[6], &mut v[7]),
                abi::SUCCESS
            );
            assert_eq!(v, [1, 2, 3, 4, 5, 6, abi::CROSS_CORRELATION, abi::DT_FLOAT]);
            assert_eq!(cudnnSetConvolutionGroupCount(c, 0), abi::BAD_PARAM);
            assert_eq!(cudnnSetConvolutionGroupCount(c, 4), abi::SUCCESS);
            assert_eq!(cudnnDestroyConvolutionDescriptor(c), abi::SUCCESS);
        }
    }

    unsafe fn tdesc(fmt: i32, n: i32, c: i32, h: i32, w: i32, dt: i32) -> Td {
        let mut t = null_mut();
        unsafe {
            cudnnCreateTensorDescriptor(&mut t);
            assert_eq!(cudnnSetTensor4dDescriptor(t, fmt, dt, n, c, h, w), abi::SUCCESS);
        }
        t
    }

    #[test]
    fn algorithm_queries_report_one_algo_or_status() {
        unsafe {
            let mut h = null_mut();
            cudnnCreate(&mut h);
            let x = tdesc(abi::NCHW, 1, 4, 8, 8, abi::DT_FLOAT);
            let y = tdesc(abi::NCHW, 1, 6, 8, 8, abi::DT_FLOAT);
            let mut w = null_mut();
            cudnnCreateFilterDescriptor(&mut w);
            cudnnSetFilter4dDescriptor(w, abi::DT_FLOAT, abi::NCHW, 6, 4, 3, 3);
            let mut c = null_mut();
            cudnnCreateConvolutionDescriptor(&mut c);
            cudnnSetConvolution2dDescriptor(c, 1, 1, 1, 1, 1, 1, abi::CROSS_CORRELATION, abi::DT_FLOAT);
            let mut perf = [perf_entry(-1, 0.0); 4];
            let mut n = -1;
            assert_eq!(cudnnGetConvolutionForwardAlgorithm_v7(h, x, w, c, y, 4, &mut n, perf.as_mut_ptr()), abi::SUCCESS);
            assert_eq!((n, perf[0].algo, perf[0].status, perf[0].memory), (1, 0, 0, 0));
            let mut ws = 99;
            assert_eq!(cudnnGetConvolutionForwardWorkspaceSize(h, x, w, c, y, 0, &mut ws), abi::SUCCESS);
            assert_eq!(ws, 0);
            // backward queries use (filter, dy, conv, dx) / (x, dy, conv, dw) orders
            assert_eq!(cudnnGetConvolutionBackwardDataAlgorithm_v7(h, w, y, c, x, 1, &mut n, perf.as_mut_ptr()), abi::SUCCESS);
            assert_eq!(cudnnGetConvolutionBackwardFilterAlgorithm_v7(h, x, y, c, w, 1, &mut n, perf.as_mut_ptr()), abi::SUCCESS);
            // double precision is reported as NOT_SUPPORTED with zero algos
            let xd = tdesc(abi::NCHW, 1, 4, 8, 8, abi::DT_DOUBLE);
            let yd = tdesc(abi::NCHW, 1, 6, 8, 8, abi::DT_DOUBLE);
            let mut wd = null_mut();
            cudnnCreateFilterDescriptor(&mut wd);
            cudnnSetFilter4dDescriptor(wd, abi::DT_DOUBLE, abi::NCHW, 6, 4, 3, 3);
            assert_eq!(cudnnGetConvolutionForwardAlgorithm_v7(h, xd, wd, c, yd, 4, &mut n, perf.as_mut_ptr()), abi::NOT_SUPPORTED);
            assert_eq!(n, 0);
            assert_eq!(cudnnGetConvolutionForwardAlgorithm_v7(h, x, w, c, y, 0, &mut n, perf.as_mut_ptr()), abi::BAD_PARAM);
        }
    }

    #[test]
    fn execution_without_driver_reports_not_initialized_not_crash() {
        // On a host without nvcuda/libcuda the launch path must fail cleanly.
        unsafe {
            let mut h = null_mut();
            cudnnCreate(&mut h);
            let x = tdesc(abi::NCHW, 1, 1, 4, 4, abi::DT_FLOAT);
            let mut w = null_mut();
            cudnnCreateFilterDescriptor(&mut w);
            cudnnSetFilter4dDescriptor(w, abi::DT_FLOAT, abi::NCHW, 1, 1, 1, 1);
            let mut c = null_mut();
            cudnnCreateConvolutionDescriptor(&mut c);
            let (a, b) = (1f32, 0f32);
            let st = cudnnConvolutionForward(
                h, &a as *const f32 as _, x, 8 as _, w, 8 as _, c, 0, null_mut(), 0, &b as *const f32 as _, x, 16 as _,
            );
            assert!(st == abi::NOT_INITIALIZED || st == abi::SUCCESS, "{st}");
            // null alpha is a BAD_PARAM
            assert_eq!(
                cudnnConvolutionForward(h, std::ptr::null(), x, 8 as _, w, 8 as _, c, 0, null_mut(), 0, &b as *const f32 as _, x, 16 as _),
                abi::BAD_PARAM
            );
        }
    }

    #[test]
    fn fold4_handles_3d_5d_and_broadcast() {
        // 5-D NCDHW bias add: A=(1,C,1,1,1) -> strides (0,1,0,0,0) vs packed C
        let (d, a, c) = fold4(&[2, 3, 4, 5, 6], &[0, 1, 0, 0, 0], &[360, 120, 30, 6, 1]).unwrap();
        assert_eq!(d, [2, 3, 4, 30]);
        assert_eq!(a, [0, 1, 0, 0]);
        assert_eq!(c, [360, 120, 30, 1]);
        // 3-D gets a trailing unit dim
        let (d, ..) = fold4(&[2, 3, 7], &[0, 1, 0], &[21, 7, 1]).unwrap();
        assert_eq!(d, [2, 3, 7, 1]);
        // non-mergeable strides are rejected
        assert_eq!(fold4(&[2, 3, 4, 5, 6], &[0, 1, 0, 0, 0], &[720, 240, 60, 13, 2]).unwrap_err(), abi::NOT_SUPPORTED);
    }

    #[test]
    fn unsupported_entry_points_return_not_supported() {
        unsafe {
            assert_eq!(stubs::cudnnSoftmaxForward(), abi::NOT_SUPPORTED);
            assert_eq!(stubs::cudnnPoolingForward(), abi::NOT_SUPPORTED);
        }
    }
}
